```js
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new THREE.Group();
  const timelines = [];
  const disposables = [];

  // Colors from config
  const colors = config.intent?.visualSpec?.colors || {};
  const gradientStops = colors.gradientStops || [
    { at: 0, hex: '#191921' },
    { at: 1, hex: '#121218' },
  ];
  const accentColor = colors.accent || '#ff2a38';
  const paperColor = colors.paper || '#e8ecf2';

  // Parse hex to normalized RGB
  const hexToRgb = (hex) => {
    const h = hex.replace('#', '');
    return [
      parseInt(h.slice(0, 2), 16) / 255,
      parseInt(h.slice(2, 4), 16) / 255,
      parseInt(h.slice(4, 6), 16) / 255,
    ];
  };

  const [r0, g0, b0] = hexToRgb(gradientStops[0].hex);
  const [r1, g1, b1] = hexToRgb(gradientStops[1].hex);

  // Backdrop plane with vertical gradient
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    colorNode: mix(vec3(r0, g0, b0), vec3(r1, g1, b1), uv().y),
    metalness: 0,
    roughness: 1,
  });
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);
  disposables.push(backdropGeom, backdropMat);

  // Key light (upper-left)
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 2, 1);
  root.add(keyLight);

  // Rim light (accent-tinted, opposite)
  const rimLight = new THREE.DirectionalLight(accentColor, 0.8);
  rimLight.position.set(-2, -1, 0.5);
  root.add(rimLight);

  // Card data
  const cardsData = [
    {
      icon: '01',
      title: 'In-House Calibre',
      body: 'Every movement is designed, machined, and finished under one roof.',
    },
    {
      icon: '02',
      title: 'Five-Year Guarantee',
      body: 'Each piece is serviced free of charge for five years from delivery.',
    },
    {
      icon: '03',
      title: 'Hand-Finished Dials',
      body: 'Guilloche cut on a 1912 rose engine, one dial at a time.',
    },
  ];

  const cardWidth = 1.5;
  const cardHeight = 1.9;
  const gapBetweenCards = 0.25;
  const totalWidth = 3 * cardWidth + 2 * gapBetweenCards;
  const startX = -totalWidth / 2 + cardWidth / 2;

  // Create three cards
  for (let i = 0; i < 3; i++) {
    const cardGroup = new THREE.Group();
    cardGroup.position.x = startX + i * (cardWidth + gapBetweenCards);
    cardGroup.position.y = 0.2; // Initial position for entrance animation

    // Card surface with gradient
    const cardGeom = new THREE.PlaneGeometry(cardWidth, cardHeight);
    const cardMat = new MeshStandardNodeMaterial({
      colorNode: mix(vec3(r0, g0, b0), vec3(r1, g1, b1), uv().y),
      metalness: 0.25,
      roughness: 0.6,
      clearcoat: 0.15,
      transparent: true,
    });
    cardMat.opacity = 0;

    const cardMesh = new THREE.Mesh(cardGeom, cardMat);
    cardMesh.position.z = 0;
    cardGroup.add(cardMesh);
    disposables.push(cardGeom, cardMat);

    // Machined disc for icon seat
    const discGeom = new THREE.CylinderGeometry(0.2, 0.2, 0.05, 32);
    const discMat = new MeshStandardNodeMaterial({
      color: 0x16161d,
      metalness: 0.5,
      roughness: 0.55,
      clearcoat: 0.2,
      anisotropy: 0.6,
    });
    discMat.emissive.setHex(0x000000);
    discMat.emissiveIntensity = 1.6;

    const disc = new THREE.Mesh(discGeom, discMat);
    disc.position.z = 0.05;
    disc.position.y = cardHeight / 2 - 0.5;
    cardGroup.add(disc);
    disposables.push(discGeom, discMat);

    // Icon glyph (emissive red text)
    const iconText = ctx.fontAtlas.createText(cardsData[i].icon, {
      fontSize: 20,
      color: accentColor,
      align: 'center',
    });
    iconText.position.z = 0.1;
    iconText.position.y = disc.position.y;
    iconText.scale.multiplyScalar(0.015);
    iconText.traverse((child) => {
      if (child.isMesh && child.material) {
        if (child.material.emissive) child.material.emissive.setStyle(accentColor);
        child.material.emissiveIntensity = 1.6;
      }
    });
    cardGroup.add(iconText);

    // Title text
    const titleText = ctx.fontAtlas.createText(cardsData[i].title, {
      fontSize: 20,
      color: paperColor,
      align: 'center',
      maxWidthPx: 280,
    });
    titleText.position.z = 0.01;
    titleText.position.y = disc.position.y - 0.45;
    titleText.scale.multiplyScalar(0.012);
    cardGroup.add(titleText);

    // Body text
    const bodyText = ctx.fontAtlas.createText(cardsData[i].body, {
      fontSize: 13,
      color: paperColor,
      align: 'center',
      maxWidthPx: 280,
    });
    bodyText.position.z = 0.01;
    bodyText.position.y = titleText.position.y - 0.35;
    bodyText.scale.multiplyScalar(0.01);
    cardGroup.add(bodyText);

    // Contact shadow plane
    const shadowGeom = new THREE.PlaneGeometry(1.8, 0.15);
    const shadowMat = new MeshBasicNodeMaterial({
      color: 0x000000,
      transparent: true,
    });
    shadowMat.opacity = 0.4;

    const shadow = new THREE.Mesh(shadowGeom, shadowMat);
    shadow.position.y = -cardHeight / 2 - 0.1;
    shadow.position.z = -0.05;
    cardGroup.add(shadow);
    disposables.push(shadowGeom, shadowMat);

    // Store references for hover
    cardGroup.userData.discMat = discMat;
    cardGroup.userData.shadowMat = shadowMat;
    cardGroup.userData.cardMat = cardMat;

    // Entrance animation: stagger fade-up
    const delay = i * 0.08;
    const tl = gsap.timeline({ delay });
    tl.to(cardGroup.position, { y: 0, duration: 0.5, ease: 'cubic.out' }, 0);
    tl.to(cardMat, { opacity: 1, duration: 0.5, ease: 'cubic.out' }, 0);
    timelines.push(tl);

    // Hover interaction handler
    cardGroup.userData.handlers = {
      hover: (isHovering) => {
        const dur = 0.18;
        const ease = 'cubic.inOut';

        if (isHovering) {
          gsap.to(cardGroup.position, { y: 0.06, z: 0.12, duration: dur, ease });
          gsap.to(discMat, { emissiveIntensity: 2.2, duration: dur, ease });
          gsap.to(shadow.scale, { x: 1.15, y: 1.15, duration: dur, ease });
          gsap.to(shadowMat, { opacity: 0.25, duration: dur, ease });
        } else {
          gsap.to(cardGroup.position, { y: 0, z: 0, duration: dur, ease });
          gsap.to(discMat, { emissiveIntensity: 1.6, duration: dur, ease });
          gsap.to(shadow.scale, { x: 1, y: 1, duration: dur, ease });
          gsap.to(shadowMat, { opacity: 0.4, duration: dur, ease });
        }
      },
    };

    root.add(cardGroup);
  }

  // Cleanup: dispose all resources and kill timelines
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((item) => {
      try {
        item?.dispose?.();
      } catch (e) {
        // Ignore disposal errors
      }
    });
    root.traverse((child) => {
      if (child.geometry) child.geometry.dispose?.();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose?.());
        } else {
          child.material.dispose?.();
        }
      }
    });
  };

  return root;
}
